// ── Backlog tools: safe read / add / update of Product Backlog tickets (#1585) ──
// A ticket is ONE file in diegonmarcos/cloudy-a-docs:
//   1___BACKLOG___/1.1.Product-Backlog/tasks/<session-id>/<id>.json
// These methods are the only MCP path that writes tickets. They never delete a
// ticket and never blank its subject or description (the corruption #1585 was
// opened for); an update merges an allowlisted set of fields and appends to
// progress instead of replacing it. The rendered index (P-Backlog.md/.html,
// dist/) is regenerated by the backlog.yml workflow on every push of the repo.
// Transport: GitHub REST contents/trees API with GITHUB_TOKEN (container
// secrets, never logged). Policy is pure and unit-tested in test-backlog.mjs.

export const BACKLOG_REPO = process.env.BACKLOG_REPO ?? "diegonmarcos/cloudy-a-docs";
export const BACKLOG_BRANCH = process.env.BACKLOG_BRANCH ?? "main";
export const TASKS_DIR = "1___BACKLOG___/1.1.Product-Backlog/tasks";
export const STATUSES = ["pending", "in_progress", "owner-pending", "completed", "deleted"] as const;
const UPDATABLE_META = ["progress", "done", "decision", "closed", "blocker", "related"] as const;

export function validId(id: unknown): string {
  const s = String(id ?? "").replace(/^#/, "");
  if (!/^[0-9]{1,6}$/.test(s)) throw new Error(`invalid ticket id '${String(id)}' (digits only)`);
  return s;
}

export function validSession(s: unknown): string {
  const v = String(s ?? "");
  if (!/^[A-Za-z0-9_-]{6,64}$/.test(v)) throw new Error(`invalid session folder '${v}'`);
  return v;
}

/** Parse the recursive tree listing into id -> path (one path per id, first wins). */
export function indexFromTree(paths: string[]): Map<string, { session: string; path: string }> {
  const out = new Map<string, { session: string; path: string }>();
  const re = new RegExp(`^${TASKS_DIR.replace(/[.]/g, "\\.")}/([A-Za-z0-9_-]+)/([0-9]+)\\.json$`);
  for (const p of paths) {
    const m = re.exec(p);
    if (m && !out.has(m[2])) out.set(m[2], { session: m[1], path: p });
  }
  return out;
}

export function nextId(index: Map<string, unknown>): string {
  let max = 0;
  for (const k of index.keys()) max = Math.max(max, Number(k));
  return String(max + 1);
}

export function newTicket(id: string, subject: string, description: string, scope?: unknown): any {
  const subj = String(subject ?? "").trim();
  const desc = String(description ?? "").trim();
  if (!subj) throw new Error("subject is required");
  if (!desc) throw new Error("description is required");
  const s = subj.startsWith(`#${id} `) ? subj : `#${id} ${subj}`;
  const t: any = { id, subject: s, description: desc, activeForm: s, status: "pending", blocks: [], blockedBy: [],
    metadata: { created: new Date().toISOString().slice(0, 10) } };
  if (scope && typeof scope === "object") t.metadata.scope = scope;
  return t;
}

/**
 * Merge an update into an existing ticket. Refuses anything that would delete
 * or blank the ticket; progress is appended (dated) rather than replaced.
 */
export function mergeUpdate(old: any, patch: any, today = new Date().toISOString().slice(0, 10)): any {
  if (!old || typeof old !== "object" || !old.id) throw new Error("existing ticket is unreadable; refusing to write");
  const p = (patch ?? {}) as Record<string, unknown>;
  for (const k of Object.keys(p)) {
    if (!["status", "subject", "description_append", ...UPDATABLE_META].includes(k)) throw new Error(`field '${k}' is not updatable through backlog.update`);
  }
  const t = JSON.parse(JSON.stringify(old));
  if (p.status !== undefined) {
    if (!(STATUSES as readonly string[]).includes(String(p.status))) throw new Error(`invalid status '${String(p.status)}'`);
    if (p.status === "deleted") throw new Error("status 'deleted' is not allowed through the MCP (tickets are never deleted)");
    t.status = p.status;
  }
  if (p.subject !== undefined) {
    const s = String(p.subject).trim();
    if (!s) throw new Error("refusing to blank the subject");
    t.subject = s.startsWith(`#${t.id} `) ? s : `#${t.id} ${s}`;
  }
  if (p.description_append !== undefined) {
    const a = String(p.description_append).trim();
    if (a) t.description = `${String(t.description ?? "").trimEnd()}\n\n${a}`;
  }
  t.metadata = t.metadata && typeof t.metadata === "object" ? t.metadata : {};
  for (const k of UPDATABLE_META) {
    if (p[k] === undefined) continue;
    const v = String(p[k]).trim();
    if (!v) throw new Error(`refusing to blank metadata.${k}`);
    if (k === "progress" && t.metadata.progress) t.metadata.progress = `${String(t.metadata.progress).trimEnd()}\n${today}: ${v}`;
    else t.metadata[k] = v;
  }
  if (t.status === "completed" && !t.metadata.closed) t.metadata.closed = today;
  if (!String(t.subject ?? "").trim() || !String(t.description ?? "").trim()) throw new Error("result would blank the ticket; refusing");
  return t;
}

// ── transport ────────────────────────────────────────────────────────────────
const API = "https://api.github.com";
async function gh(method: string, path: string, body?: unknown): Promise<any> {
  const token = process.env.GITHUB_TOKEN ?? "";
  if (!token) throw new Error("GITHUB_TOKEN is not set in the container (src/secrets.yaml)");
  const r = await fetch(`${API}${path}`, {
    method,
    headers: { Authorization: `Bearer ${token}`, Accept: "application/vnd.github+json", "User-Agent": "c3-backlog", ...(body ? { "Content-Type": "application/json" } : {}) },
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(20_000),
  });
  const text = await r.text();
  if (!r.ok) throw new Error(`GitHub ${method} ${path.split("?")[0]} -> ${r.status}: ${text.slice(0, 300)}`);
  return text ? JSON.parse(text) : {};
}

async function loadIndex() {
  const tree = await gh("GET", `/repos/${BACKLOG_REPO}/git/trees/${BACKLOG_BRANCH}?recursive=1`);
  return indexFromTree((tree.tree ?? []).map((e: any) => String(e.path)));
}

async function readTicket(path: string): Promise<{ sha: string; ticket: any }> {
  const f = await gh("GET", `/repos/${BACKLOG_REPO}/contents/${encodeURI(path)}?ref=${BACKLOG_BRANCH}`);
  return { sha: f.sha, ticket: JSON.parse(Buffer.from(String(f.content ?? ""), "base64").toString("utf8")) };
}

async function writeTicket(path: string, ticket: any, message: string, sha?: string) {
  const content = Buffer.from(JSON.stringify(ticket, null, 2) + "\n", "utf8").toString("base64");
  return gh("PUT", `/repos/${BACKLOG_REPO}/contents/${encodeURI(path)}`, { message, content, branch: BACKLOG_BRANCH, ...(sha ? { sha } : {}) });
}

/** Dispatch for infra.devops backlog.* methods. */
export async function handleBacklog(method: string, p: any): Promise<string> {
  switch (method) {
    case "list": {
      const idx = await loadIndex();
      const ids = [...idx.keys()].map(Number).sort((a, b) => b - a);
      const limit = Math.min(Math.max(Number(p.limit ?? 50), 1), 500);
      return JSON.stringify({ repo: BACKLOG_REPO, total: ids.length, next_id: nextId(idx),
        tickets: ids.slice(0, limit).map((n) => ({ id: String(n), session: idx.get(String(n))!.session })) }, null, 2);
    }
    case "get": {
      const id = validId(p.id);
      const hit = (await loadIndex()).get(id);
      if (!hit) throw new Error(`ticket #${id} not found`);
      return JSON.stringify({ path: hit.path, ticket: (await readTicket(hit.path)).ticket }, null, 2);
    }
    case "add": {
      const session = validSession(p.session);
      const idx = await loadIndex();
      const id = nextId(idx);
      const t = newTicket(id, p.subject, p.description, p.scope);
      const path = `${TASKS_DIR}/${session}/${id}.json`;
      await writeTicket(path, t, `backlog: add #${id} (c3 MCP)`);
      return JSON.stringify({ added: id, path }, null, 2);
    }
    case "update": {
      const id = validId(p.id);
      const hit = (await loadIndex()).get(id);
      if (!hit) throw new Error(`ticket #${id} not found`);
      const { sha, ticket } = await readTicket(hit.path);
      const next = mergeUpdate(ticket, p.patch ?? {});
      await writeTicket(hit.path, next, `backlog: update #${id} (c3 MCP)`, sha);
      return JSON.stringify({ updated: id, path: hit.path, status: next.status }, null, 2);
    }
    default:
      throw new Error(`unknown backlog method '${method}'`);
  }
}
